    if num is None:
        return "-"
    a = abs(num)
    for div, suf in ((1e12, "T"), (1e9, "B"), (1e6, "M"), (1e3, "K")):
        if a >= div:
            s = "%.2f%s" % (a / div, suf)
            break
    else:
        s = "%.2f" % a
    return "-" + s if num < 0 else s


